with cleaned as (select id, email, country, signup_date, is_active, credit_limit, age, concat(country, ', ', name) as country_name, credit_limit + age as credit_limit_plus_age, coalesce(city, 'N/A') as city_clean from customers where credit_limit between 13300 and 15400) select id, email, country, signup_date, is_active, credit_limit, age, country_name, credit_limit_plus_age, city_clean, avg(credit_limit) over (order by credit_limit, id rows between 5 preceding and current row) as credit_limit_avg_5, sum(age) over (order by credit_limit, id rows between unbounded preceding and current row) as cumulative_age, sum(credit_limit_plus_age) over (partition by country) as country_sum_credit_limit_plus_age, sum(credit_limit) over (partition by country order by age, id rows between unbounded preceding and current row) as cumulative_credit_limit from cleaned;
